46: void VRotTransMatrixNew( Uint8& packed,
47: 				   const float* m )
48: {
49:   packed = 0;
50: 
51:   double  trace = 1.0 + m[ 0 ] + m[ 4 ] + m[ 8 ];
52:   double  s, qw, qx, qy, qz; 
53:   if ( 0.1 < trace ) {  // Default
54:     s = 2.0 * sqrt( trace );
55:     qw = 0.25 * s;
56:     double  s_invert = 1.0 / s;
57:     qx = ( m[ 7 ] - m[ 5 ] ) * s_invert;
58:     qy = ( m[ 2 ] - m[ 6 ] ) * s_invert;
59:     qz = ( m[ 3 ] - m[ 1 ] ) * s_invert;
60:     ////// PUBCHEM_INFO( "0 trace: " << trace
61:     //              << "  (Q: " << qw << " " << qx << " " << qy << " " << qz << ")"
62:     //              << "  (M: " << m[0] << " " << m[4] << " " << m[8] << ")" );
63:   } else if ( 0.005 < ( m[ 0 ] - m[ 4 ] ) &&
64: 	      0.005 < ( m[ 0 ] - m[ 8 ] ) ) {  // X is largest
65:     s = 2.0 * sqrt( 1.0 + m[ 0 ] - m[ 4 ] - m[ 8 ] );
66:     double  s_invert = 1.0 / s;
67:     qw = ( m[ 7 ] - m[ 5 ] ) * s_invert;
68:     qx = 0.25 * s;
69:     qy = ( m[ 3 ] + m[ 1 ] ) * s_invert;
70:     qz = ( m[ 2 ] + m[ 6 ] ) * s_invert;
71:     ////// PUBCHEM_INFO( "1 trace: " << trace
72:     //              << "  (Q: " << qw << " " << qx << " " << qy << " " << qz << ")"
73:     //              << "  (M: " << m[0] << " " << m[4] << " " << m[8] << ")" );
74:   } else if ( 0.005 < ( m[ 4 ] - m[ 8 ] ) ) {  // Y is largest
75:     s = 2.0 * sqrt( 1.0 + m[ 4 ] - m[ 0 ] - m[ 8 ] );
76:     double  s_invert = 1.0 / s;
77:     qw = ( m[ 2 ] - m[ 6 ] ) * s_invert;
78:     qx = ( m[ 3 ] + m[ 1 ] ) * s_invert;
79:     qy = 0.25 * s;
80:     qz = ( m[ 7 ] + m[ 5 ] ) * s_invert;
81:     ////// PUBCHEM_INFO( "2 trace: " << trace
82:     //              << "  (Q: " << qw << " " << qx << " " << qy << " " << qz << ")"
83:     //              << "  (M: " << m[0] << " " << m[4] << " " << m[8] << ")" );
84:   } else {    // Z is largest
85:     s = 2.0 * sqrt( 1.0 + m[ 8 ] - m[ 0 ] - m[ 4 ] );
86:     double  s_invert = 1.0 / s;
87:     qw = ( m[ 3 ] - m[ 1 ] ) * s_invert;
88:     qx = ( m[ 2 ] + m[ 6 ] ) * s_invert;
89:     qy = ( m[ 7 ] + m[ 5 ] ) * s_invert;
90:     qz = 0.25 * s;
91:     ////// PUBCHEM_INFO( "3 trace: " << trace
92:     //              << "  (Q: " << qw << " " << qx << " " << qy << " " << qz << ")"
93:     //              << "  (M: " << m[0] << " " << m[4] << " " << m[8] << ")" );
94:   }
95: 
96:   // Encode Quaternion
97:   static const unsigned  rbase  = 0xFF;  // Rotation base
98:   static const double  cr = static_cast< double >( rbase ) / 2.0;
99: 
100:   // Normalize
101:   s = cr / sqrt( qw * qw + qx * qx + qy * qy + qz * qz );
102: 
103:   Uint8  p1 = static_cast< Uint8 >( rint( cr + ( qw * s ) ) );
104:   Uint8  p2 = static_cast< Uint8 >( rint( cr + ( qx * s ) ) );
105:   Uint8  p3 = static_cast< Uint8 >( rint( cr + ( qy * s ) ) );
106:   Uint8  p4 = static_cast< Uint8 >( rint( cr + ( qz * s ) ) );
107:   if ( rbase < p1 ) {
108:     //// //// PUBCHEM_WARN( "Qw encoding is corrupt (0-255 range)!  " << p1 << " " << qw * s );
109:   }
110:   if ( rbase < p2 ) {
111:     //// //// PUBCHEM_WARN( "Qx encoding is corrupt (0-255 range)!  " << p2 << " " << qx * s );
112:   }
113:   if ( rbase < p3 ) {
114:     //// //// PUBCHEM_WARN( "Qy encoding is corrupt (0-255 range)!  " << p3 << " " << qy * s );
115:   }
116:   if ( rbase < p4 ) {
117:     //// //// PUBCHEM_WARN( "Qz encoding is corrupt (0-255 range)!  " << p4 << " " << qz * s );
118:   }
119: 
120:   // Encode Translation
121:   static const unsigned  tbase = static_cast< unsigned >( pow( static_cast< double >( 0x1FFFFFFF ), ( 1.0 / 3.0 ) ) );
122:   static const unsigned  tbase2 = tbase * tbase;
123:   static const double  itresolution = static_cast< double >( tbase ) / log( 101. );
124: 
125:   double  x = m[  9 ];  // X
126:   if ( x < 0.0 ) {
127:     packed |= 0x01;
128:     x = -x;
129:   }
130:   x = log( 1.0 + x );
131:   Uint8  p5 = static_cast< Uint8 >( rint( x * itresolution ) );
132:   if ( p5 >= tbase ) {  // Range check
133:     p5 = tbase - 1;
134:     //// //// PUBCHEM_WARN( "X axis translation abs(" << m[  9 ] << ") is beyond maximum range of " << PubChem::Data::expPackedNew2[ p5 ] );
135:   }
136: 
137:   double  y = m[ 10 ];  // Y
138:   if ( y < 0.0 ) {
139:     packed |= 0x02;
140:     y = -y;
141:   }
142:   y = log( 1.0 + y );
143:   Uint8  p6 = static_cast< Uint8 >( rint( y * itresolution ) );
144:   if ( p6 >= tbase ) {  // Range check
145:     p6 = tbase - 1;
146:     //// //// PUBCHEM_WARN( "Y axis translation abs(" << m[ 10 ] << ") is beyond maximum range of " << PubChem::Data::expPackedNew2[ p6 ] );
147:   }
148: 
149:   double  z = m[ 11 ];  // Z
150:   if ( z < 0.0 ) {
151:     packed |= 0x04;
152:     z = -z;
153:   }
154:   z = log( 1.0 + z );
155:   Uint8  p7 = static_cast< Uint8 >( rint( z * itresolution ) );
156:   if ( p7 >= tbase ) {  // Range check
157:     p7 = tbase - 1;
158:     //// //// PUBCHEM_WARN( "Z axis translation abs(" << m[ 11 ] << ") is beyond maximum range of " << PubChem::Data::expPackedNew2[ p7 ] );
159:   }
160: 
161:   Uint8  pt = p5 * tbase2 + p6 * tbase + p7;
162: 
163:   // Pack matrix
164:   packed |= ( ( p1 & rbase ) << 56 ); // Qw
165:   packed |= ( ( p2 & rbase ) << 48 ); // Qy
166:   packed |= ( ( p3 & rbase ) << 40 ); // Qx
167:   packed |= ( ( p4 & rbase ) << 32 ); // Qz
168:   packed |= ( ( pt & 0x1FFFFFFF ) << 3 );  // X,Y,Z
