173: void VQuaternionTransArray2RotTransMatrix( double* m,
174: 						     const double* q,
175: 						     const bool normalize )
176: {
177:   double  q00 = q[ 0 ];
178:   double  q01 = q[ 1 ];
179:   double  q02 = q[ 2 ];
180:   double  q03 = q[ 3 ];
181: 
182:   // Normalize quaternion
183:   if ( true == normalize ) {
184:     double  s = 1.0 / sqrt( q00 * q00 + q01 * q01 + q02 * q02 + q03 * q03 );
185:     q00 *= s;
186:     q01 *= s;
187:     q02 *= s;
188:     q03 *= s;
189:   }
190: 
191:   double  sqw = q00 * q00;
192:   double  sqx = q01 * q01;
193:   double  sqy = q02 * q02;
194:   double  sqz = q03 * q03;
195: 
196:   double  qxqy = q01 * q02;
197:   double  qwqz = q00 * q03;
198: 
199:   double  qxqz = q01 * q03;
200:   double  qwqy = q00 * q02;
201: 
202:   double  qyqz = q02 * q03;
203:   double  qwqx = q00 * q01;
204: 
205:   // Left-handed rotation matrix
206:   m[  0 ] = sqw + sqx - sqy - sqz;  // X X
207:   m[  1 ] = 2.0 * ( qxqy - qwqz );  // X Y
208:   m[  2 ] = 2.0 * ( qxqz + qwqy );  // X Z
209:   m[  3 ] = 2.0 * ( qxqy + qwqz );  // Y X
210:   m[  4 ] = sqw - sqx + sqy - sqz;  // Y Y
211:   m[  5 ] = 2.0 * ( qyqz - qwqx );  // Y Z
212:   m[  6 ] = 2.0 * ( qxqz - qwqy );  // Z X
213:   m[  7 ] = 2.0 * ( qyqz + qwqx );  // Z Y
214:   m[  8 ] = sqw - sqx - sqy + sqz;  // Z Z
215:   m[  9 ] = q[ 4 ];
216:   m[ 10 ] = q[ 5 ];
217:   m[ 11 ] = q[ 6 ];
