296: void VRotTransMatrix2QuaternionTransArray( double* q,
297: 						     const double* m )
298: {
299:   double  trace = 1.0 + m[ 0 ] + m[ 4 ] + m[ 8 ];
300:   double  s, qw, qx, qy, qz;
301:   if ( trace > 0.00001 ) {
302:     s = 2.0 * sqrt( trace );
303:     qw = 0.25 * s;
304:     double  s_invert = 1.0 / s;
305:     qx = ( m[ 7 ] - m[ 5 ] ) * s_invert;
306:     qy = ( m[ 2 ] - m[ 6 ] ) * s_invert;
307:     qz = ( m[ 3 ] - m[ 1 ] ) * s_invert;
308:     ////// PUBCHEM_INFO( "0 trace: " << trace << "  " << qw << " " << qx << " " << qy << " " << qz );
309:   } else if ( m[ 0 ] > m[ 4 ] &&
310: 	      m[ 0 ] > m[ 8 ] ) {
311:     s = 2.0 * sqrt( 1.0 + m[ 0 ] - m[ 4 ] - m[ 8 ] );
312:     double  s_invert = 1.0 / s;
313:     qw = ( m[ 7 ] - m[ 5 ] ) * s_invert;
314:     qx = 0.25 * s;
315:     qy = ( m[ 3 ] + m[ 1 ] ) * s_invert;
316:     qz = ( m[ 2 ] + m[ 6 ] ) * s_invert;
317:     ////// PUBCHEM_INFO( "1 trace: " << trace << "  " << qw << " " << qx << " " << qy << " " << qz );
318:   } else if ( m[ 4 ] > m[ 8 ] ) {
319:     s = 2.0 * sqrt( 1.0 + m[ 4 ] - m[ 0 ] - m[ 8 ] );
320:     double  s_invert = 1.0 / s;
321:     qw = ( m[ 2 ] - m[ 6 ] ) * s_invert;
322:     qx = ( m[ 3 ] + m[ 1 ] ) * s_invert;
323:     qy = 0.25 * s;
324:     qz = ( m[ 7 ] + m[ 5 ] ) * s_invert;
325:     ////// PUBCHEM_INFO( "2 trace: " << trace << "  " << qw << " " << qx << " " << qy << " " << qz );
326:   } else {
327:     s = 2.0 * sqrt( 1.0 + m[ 8 ] - m[ 0 ] - m[ 4 ] );
328:     double  s_invert = 1.0 / s;
329:     qw = ( m[ 3 ] - m[ 1 ] ) * s_invert;
330:     qx = ( m[ 2 ] + m[ 6 ] ) * s_invert;
331:     qy = ( m[ 7 ] + m[ 5 ] ) * s_invert;
332:     qz = 0.25 * s;
333:     ////// PUBCHEM_INFO( "3 trace: " << trace << "  " << qw << " " << qx << " " << qy << " " << qz );
334:   }
335: 
336:   // Normalize
337:   s = 1.0 / sqrt( qw * qw + qx * qx + qy * qy + qz * qz );
338:   q[ 0 ] = qw * s;
339:   q[ 1 ] = qx * s;
340:   q[ 2 ] = qy * s;
341:   q[ 3 ] = qz * s;
342: 
343:   q[ 4 ] = m[  9 ];
344:   q[ 5 ] = m[ 10 ];
345:   q[ 6 ] = m[ 11 ];
346: }
