357: void VStericFrameRotation( float* m,     // float[ 9 ]
358: 				     const float* coord, // float[ n * 3 ]
359: 				     const unsigned n,
360: 				     float* ev )   // float[ 3 ]
361: {
362:   /*
363:     std::cerr << "*** COORDINATES: " << std::endl;
364: 
365:     for ( unsigned  i = 0;  i < n;  ++i ) {
366:       std::cerr << "\t" << coord[3*i]
367: 		<< "\t" << coord[3*i+1]
368: 		<< "\t" << coord[3*i+2]
369: 		<< std::endl;
370:     }
371:   */
372:   
373:     // Compute initial inertial tensor
374:     double  it[ 3 ][ 3 ];
375:     double  sx = coord[ 0 ], sy = coord[ 1 ], sz = coord[ 2 ];
376:     double  xx = sx * sx, yy = sy * sy, zz = sz * sz;
377:     it[ 0 ][ 0 ] = yy + zz;
378:     it[ 1 ][ 1 ] = xx + zz;
379:     it[ 2 ][ 2 ] = xx + yy;
380:     it[ 0 ][ 1 ] = sx * sy;
381:     it[ 0 ][ 2 ] = sx * sz;
382:     it[ 1 ][ 2 ] = sy * sz;
383:     for ( unsigned  i = 1;  i < n;  ++i ) {
384:         sx = coord[     i * 3 ];
385:         sy = coord[ 1 + i * 3 ];
386:         sz = coord[ 2 + i * 3 ];
387: 
388:         xx = sx * sx;
389:         yy = sy * sy;
390:         zz = sz * sz;
391: 
392:         it[ 0 ][ 0 ] += yy + zz;
393:         it[ 1 ][ 1 ] += xx + zz;
394:         it[ 2 ][ 2 ] += xx + yy;
395:         it[ 0 ][ 1 ] += sx * sy;
396:         it[ 0 ][ 2 ] += sx * sz;
397:         it[ 1 ][ 2 ] += sy * sz;
398:     }
399: 
400:     /*
401:     std::cerr << "*** Begin MATRIX: " << std::endl;
402:     for ( unsigned  i = 0;  i < 3;  ++i ) {
403:           for ( unsigned  j = 0;  j < 3;  ++j ) {
404: 	    std::cerr << "\t" << it[i][j];
405: 	  }
406: 	  std::cerr << std::endl;
407: 	  }
408:     */
409:     
410: 
411:     // Diagonalize 3x3 steric inertial tensor matrix using Jacobi Diagonalization method
412: 
413:     // Initialize eigenvectors
414:     m[  0 ] = 1.0;
415:     m[  1 ] = 0.0;
416:     m[  2 ] = 0.0;
417:     m[  3 ] = 0.0;
418:     m[  4 ] = 1.0;
419:     m[  5 ] = 0.0;
420:     m[  6 ] = 0.0;
421:     m[  7 ] = 0.0;
422:     m[  8 ] = 1.0;
423:     m[  9 ] = 0.0;
424:     m[ 10 ] = 0.0;
425:     m[ 11 ] = 0.0;
426:   
427:     // Initialize eigenvalues
428:     double  e[ 3 ];
429:     e[ 0 ] = it[ 0 ][ 0 ];
430:     e[ 1 ] = it[ 1 ][ 1 ];
431:     e[ 2 ] = it[ 2 ][ 2 ];
432: 
433:     // Main iteration loop for numerical modification
434:     const unsigned  max_iter = 50;
435:     const double  convergence_threshold = 0.000001;
436:     double  sum;       // Sum of off-diagonal elements
437:     double  s, c, t;  // sin, cos, tan of rotation angle
438:     double  g, h, tz, tau, theta;  // More temporary storage
439:     double  thresh, thresh_val = 1.0 / ( 5.0 * 3.0 * 3.0 );
440:     if ( n > 1 ) {
441:         for ( unsigned  iter = 0;  iter++ < max_iter;  ) {
442:             // Test for convergence 
443:             sum = fabs( it[ 0 ][ 1 ] ) + fabs( it[ 0 ][ 2 ] ) + fabs( it[ 1 ][ 2 ] );
444:             if ( sum < convergence_threshold ) {
445:                 break;  // Convergence reached
446:             }
447: 
448:             if ( 4 > iter ) {
449:                 thresh = sum * thresh_val;
450:             } else {
451:                 thresh = 0.0;
452:             }
453: 
454:             // Modify off diagonal elements in the attempt to make them (near) zero
455:             for ( unsigned  p = 0;  p < 2;  p++ ) {
456:                 for ( unsigned  q = p + 1;  q < 3;  q++ ) {
457:                     g = 100.0 * fabs( it[ p ][ q ] );
458:                     if ( 4 < iter &&
459:                          g < convergence_threshold ) {
460:                         it[ p ][ q ] = 0.0;  // Almost or at zero... so make it zero
461:                     } else if ( thresh < fabs( it[ p ][ q ] ) ) {
462:                         // Calculate Jacobi transformation
463:                         if ( g < convergence_threshold ) {
464:                             t = it[ p ][ q ] / ( e[ q ] - e[ p ] );
465:                         } else {
466:                             theta = ( e[ q ] - e[ p ] ) / ( 2.0 * it[ p ][ q ] );
467:                             if ( 0.0 > theta ) {
468:                                 t = -1.0 / ( sqrt( 1.0 + ( theta * theta ) ) - theta );
469:                             } else {
470:                                 t = 1.0 / ( sqrt( 1.0 + ( theta * theta ) ) + theta );
471:                             }
472:                         }
473: 
474:                         c = 1.0 / sqrt( 1.0 + ( t * t ) );
475:                         s = t * c;
476:                         tau = s / ( 1.0 + c );
477:                         tz = t * it[ p ][ q ];
478: 
479:                         it[ p ][ q ] = 0.0;
480: 
481:                         // Apply Jacobi transformation
482:                         for ( unsigned  r = 0;  r < p;  r++ ) {
483:                             g = it[ r ][ p ];
484:                             h = it[ r ][ q ];
485:                             it[ r ][ p ] = g - s * ( h + g * tau );
486:                             it[ r ][ q ] = h + s * ( g - h * tau );
487:                         }
488:                         for ( unsigned  r = p + 1;  r < q;  r++ ) {
489:                             g = it[ p ][ r ];
490:                             h = it[ r ][ q ];
491:                             it[ p ][ r ] = g - s * ( h + g * tau );
492:                             it[ r ][ q ] = h + s * ( g - h * tau );
493:                         }
494:                         for ( unsigned  r = q + 1;  r < 3;  r++ ) {
495:                             g = it[ p ][ r ];
496:                             h = it[ q ][ r ];
497:                             it[ p ][ r ] = g - s * ( h + g * tau );
498:                             it[ q ][ r ] = h + s * ( g - h * tau );
499:                         }
