131: void ComputeOverlapAndAnalyticGradient(
132: 						 double& o,                                                  // overlap
133: 						 double* g,                                                  // gradient[ 7 ]
134: 						 const double* m,                                            // rotation/translation matrix [ 12 ]
135: 						 const float* ref_coord,                                     // per ref atom, XYZ coordinates [3*nref]
136: 						 const std::vector<double>& alpha_ref_vector,
137: 						 const std::vector< unsigned >& ref_volume_atom_index_vector,
138: 						 const float* fit_coord,                                     // original per fit atom, XYZ coordinates [3*nfit]
139: 						 const std::vector<double>& alpha_fit_vector,
140: 						 const std::vector< unsigned >& fit_volume_atom_index_vector,
141: 						 bool needGrad
142: 						 )
143: {
144:   // Initialize shape volume overlap and its gradient
145:   o = 0.0;
146:   if( needGrad ){
147:     memset( g, 0, 7 * sizeof( double ) );
148:   }
149:   
150:   // Loop over atoms
151:   for( unsigned i : fit_volume_atom_index_vector ){
152:     // Transform original coordinates
153:     const double  old_x = fit_coord[ ( i * 3 )     ];
154:     const double  old_y = fit_coord[ ( i * 3 ) + 1 ];
155:     const double  old_z = fit_coord[ ( i * 3 ) + 2 ];
156: 
157:     double x, y, z;
158:     if( m == NULL ){
159:       x = old_x;
160:       y = old_y;
161:       z = old_z;
162:     }else{ 
163:       x = m[  9 ] + m[ 0 ] * old_x + m[ 1 ] * old_y + m[ 2 ] * old_z;
164:       y = m[ 10 ] + m[ 3 ] * old_x + m[ 4 ] * old_y + m[ 5 ] * old_z;
165:       z = m[ 11 ] + m[ 6 ] * old_x + m[ 7 ] * old_y + m[ 8 ] * old_z;
166:     }
167:     
168:     // Since we are applying the derivative on transformed coordinates, quaternion is (1, 0, 0, 0).
169:     
170:       
171:     for( unsigned j : ref_volume_atom_index_vector ){
172:       double x_diff = ref_coord[ ( j * 3 )     ] - x;
173:       double y_diff = ref_coord[ ( j * 3 ) + 1 ] - y;
174:       double z_diff = ref_coord[ ( j * 3 ) + 2 ] - z;
175: 	
176:       double d2 = x_diff * x_diff + y_diff * y_diff + z_diff * z_diff;
177:       if ( d2 < getD2CutOff() ) {
178: 	// Overlap
179: 
180: 	double alpha1 = alpha_fit_vector[i];
181: 	double alpha2 = alpha_ref_vector[j];
182: 	double a_ak = getA_ak( alpha1, alpha2 );
183: 	double a_oe = getOverlap0( alpha1, alpha2 );
184: 	double expMinus_ = exp( - d2 * a_ak );
185: 	o += a_oe * expMinus_;
186: 	
187: 	// Gradient terms
188: 	if (needGrad ){
189: 	
190: 	  double derivative0_ = -2.0 * a_oe * a_ak;
191: 	
192: 	  x_diff *= derivative0_ * expMinus_;
193: 	  y_diff *= derivative0_ * expMinus_;
194: 	  z_diff *= derivative0_ * expMinus_;
195: 	  
196: 	  const double  xp2 = x + x;
197: 	  const double  yp2 = y + y;
198: 	  const double  zp2 = z + z;
199: 	  
200: 	  // Gradient
201: 	  g[ 0 ] += x_diff * xp2;
202: 	  //            g[ 1 ] += x_diff * dxdx;
203: 	  g[ 2 ] += x_diff * zp2;
204: 	  g[ 3 ] -= x_diff * yp2;  // -
205: 	  g[ 4 ] += x_diff;  // Tx
206: 	  
207: 	  g[ 0 ] += y_diff * yp2;
208: 	  g[ 1 ] -= y_diff * zp2;  // -
209: 	  //            g[ 2 ] += y_diff * dydy;
210: 	  g[ 3 ] += y_diff * xp2;
211: 	  g[ 5 ] += y_diff;  // Ty
212: 	  
213: 	  g[ 0 ] += z_diff * zp2;
214: 	  g[ 1 ] += z_diff * yp2;
215: 	  g[ 2 ] -= z_diff * xp2;  // -
216: 	  //            g[ 3 ] += z_diff * dzdz;
217: 	  g[ 6 ] += z_diff;  // Tz
218: 	}
219:       }
220:     }
221:   }
222: }
