49: void Neighbor_Conformers(
50: 				      const float* ref_coord,
51: 				      const std::vector<double>& alpha_ref_vector,
52: 				      const std::vector< unsigned >& ref_volumeAtomIndexVector,
53: 				      const std::map< unsigned, std::vector< unsigned > >& ref_colorAtomType2IndexVectorMap,
54: 				      const double ref_sov,
55: 				      const double ref_sof,
56: 				      const float* fit_coord,
57: 				      const std::vector<double>& alpha_fit_vector,
58: 				      const std::vector< unsigned >& fit_volumeAtomIndexVector,
59: 				      const std::map< unsigned, std::vector< unsigned > >& fit_colorAtomType2IndexVectorMap,
60: 				      const double fit_sov,
61: 				      const double fit_sof,
62: 				      const bool considerColorAtoms,
63: 				      const unsigned max_preiters,
64: 				      const unsigned max_postiters,
65: 				      const double opt_param,
66: 				      float* matrix,
67: 				      double& nbr_st,
68: 				      double& nbr_ct
69: 				      ){
70:   
71:   if (debug_print0) {
72:     std::cerr << "debug_print1: " << debug_print1 << std::endl;
73:     std::cerr << "debug_print2: " << debug_print2 << std::endl;
74:   }
75:   
76:   // Sums needed for further use
77:   const double  st_sum_sov = ( ref_sov + fit_sov );  
78:   const double ct_sum_sov = ( ref_sof + fit_sof );
79: 
80:   double st_ratio = static_cast<double>(0);
81:   {
82:     double minSov = std::min( ref_sov, fit_sov );
83:     if( st_sum_sov > minSov ){
84:       st_ratio = minSov/( st_sum_sov - minSov );
85:     }
86:   }
87: 
88:   double ct_ratio = static_cast<double>(0);
89:   {
90:     double minSof = std::min( ref_sof, fit_sof );
91:     if( ct_sum_sov > minSof ){
92:       ct_ratio = minSof/( ct_sum_sov - minSof );
93:     }
94:   }
95:        
96:   // Qrat stuff
97:   const float qrat_threshold = 0.7225; // 0.85*0.85;
98:     
99:   unsigned ref_qrat = 1000;
100:   {
101:     std::vector< float > ref_coord_work_vec(alpha_ref_vector.size() * 3);
102:     memcpy(&(ref_coord_work_vec[0]), ref_coord, (alpha_ref_vector.size() * 3 * sizeof(float)));
103:     TransformCoordToStericFrameAndCalculateQrat( alpha_ref_vector.size(), qrat_threshold, &( ref_coord_work_vec[0] ), ref_qrat );
104:   }
105:   unsigned fit_qrat = 1000;
106:   {
107:     std::vector< float > fit_coord_work_vec(alpha_fit_vector.size() * 3);
108:     memcpy(&(fit_coord_work_vec[0]), fit_coord, (alpha_fit_vector.size() * 3 * sizeof(float)));
109:     TransformCoordToStericFrameAndCalculateQrat( alpha_fit_vector.size(), qrat_threshold, &( fit_coord_work_vec[0] ), fit_qrat );
110:   }
111: 
112:   bool is_qrat_nonzero = (ref_qrat > 0 || fit_qrat > 0);
113:   
114:   unsigned  npose = 0;
115:   if( is_qrat_nonzero ){
116:     npose = 16;
117:   }else{
118:     npose = 4;
119:   }
120: 
121:   if( debug_print1 ) std::cerr << "*** st_sum_sov: " << st_sum_sov << std::endl;
122:   if( debug_print1 ) std::cerr << "*** ct_sum_sov: " << ct_sum_sov << std::endl;
123:   if( debug_print1 ) std::cerr << "*** st_ratio: " << st_ratio << std::endl;
124:   if( debug_print1 ) std::cerr << "*** ct_ratio: " << ct_ratio << std::endl;
125: 
126:   // Globally best
127:   
128:   nbr_st = static_cast<double>(0);
129:   nbr_ct = static_cast<double>(0);
130:   double nbr_comb_prelim = static_cast<double>(0);
131:   double nbr_comb = static_cast<double>(0);
132:   double  best_qom[ 7 ];  // Best quaternion/trans matrix (optimized neighbor pose)
133:     
134:   double  best_qom_pose[ 16 ][ 7 ];
135:   double  best_mom_pose[ 16 ][ 12 ];
136:   
137:   if( debug_print1 ) std::cerr << "^^^*** max_preiters: " << max_preiters << std::endl;
138:   if( debug_print1 ) std::cerr << "^^^*** max_postiters: " << max_postiters << std::endl;
139:   if( debug_print1 ) std::cerr << "^^^*** st_sum_sov: " << st_sum_sov << std::endl;
140:   if( debug_print1 ) std::cerr << "^^^*** ct_sum_sov: " << ct_sum_sov << std::endl;
141:   if( debug_print1 ) std::cerr << "^^^*** considerColorAtoms: " << considerColorAtoms << std::endl;
142:   if( debug_print1 ) std::cerr << "*** npose: " << npose << std::endl;
143:   if( debug_print1 ) std::cerr << std::endl;
144: 
145:   // Preparing initial poses
146:   
147:   for ( unsigned  ibest_pose = 0;  ibest_pose < npose;  ibest_pose++ ) {
148:     
149:     if( debug_print1 ) std::cerr << "Processing initial pose: " << ibest_pose << "\t is_qrat_nonzero: " << is_qrat_nonzero << "\t  npose: " << npose << std::endl;
150:       
151:     // Point to appropriate transformation matrix for steric pose
152:       
153:     double  qom[ 7 ];  // Grid-based pose 4x1 quaternion vector and 3x1 translation vector
154:     const double  *mom;  // Grid-based pose 3x3 rotation matrix and 3x1 translation vector
155:     double  st_tot = (double ) 0;  // AB volume overlap
156:     double  g[ 7 ];  // Analytic gradient for 4x1 quaternion vector and 3x1 translation vector (really 6x1 since [0] element is zero)
157: 
158:     if( debug_print1 ) std::cerr << "\tBefore qrat-based selection of poses, is_qrat_nonzero: " << is_qrat_nonzero << " st_tot: " << st_tot << std::endl;
159:     
160:     if ( is_qrat_nonzero ) {
161:       
162:       if( debug_print1 ) std::cerr << "\t\tis_qrat_nonzero: " << is_qrat_nonzero << " -- Select mom for ibest_pose, where ibest_pose=" << ibest_pose << std::endl;
163: 
164:       memcpy( best_qom_pose[ ibest_pose ], qmatrix_typed[ ibest_pose ], 7 * sizeof( double ) );    
165:       memcpy( best_mom_pose[ ibest_pose ], matrix_typed[ ibest_pose ], 12 * sizeof( double ) );
166:     } else {
167:       if( debug_print1 ) std::cerr << "\t\tis_qrat_nonzero: " << is_qrat_nonzero << " -- Select 8 mom's for ibest_pose, where ibest_pose=" << ibest_pose << std::endl;
168:       
169:       // Find best m_loc_ from mloc_ = 0, 1, ..., 6, set it to m_loc, and apply insyed of the best pose from the grid
170:       unsigned m_loc = 0;
171:       double F = (double ) -1;
172:       for ( unsigned  m_loc_ = 0; m_loc_ < 7; ++m_loc_ ){
173: 	double  mc[ 12 ];  // Scratch array for rot/trans matrix	  
174: 	memcpy( qom, pqmatrix_typed[ ibest_pose ][ m_loc_ ], 7 * sizeof( double ) );
175: 	mom = pmatrix_typed[ ibest_pose ][ m_loc_ ];
176: 	
177: 	ComputeOverlapAndAnalyticGradient(
178: 					 st_tot,   
179: 					 g,   
180: 					 mom,   
181: 					 ref_coord,
182: 					 alpha_ref_vector,
183: 					 ref_volumeAtomIndexVector,
184: 					 fit_coord,
185: 					 alpha_fit_vector,
186: 					 fit_volumeAtomIndexVector
187: 					  );
188: 
189: 	// Compute shape Tanimoto
190: 	double fst = 0.0; 
191: 	if( st_sum_sov > 0 && st_sum_sov > st_tot ){
192: 	  fst = st_tot / ( st_sum_sov - st_tot );
193: 	}
194: 
195: 	// Compute feature Tanimoto
196: 	double ct_tot = 0.0;
197: 	double fct = 0.0;
198: 	if( considerColorAtoms ){
199: 	  if( ct_sum_sov > 0 ){
200: 	    VQuaternionTransArray2RotTransMatrix( mc, qom, false );  // Already normalized
201: 	    ct_tot = ComputeFeatureOverlap(
202: 					   ref_coord,
203: 					   alpha_ref_vector,
204: 					   ref_colorAtomType2IndexVectorMap,
205: 					   fit_coord,
206: 					   alpha_fit_vector,
207: 					   fit_colorAtomType2IndexVectorMap,
208: 					   mc
209: 					   );
210: 
211: 
212: 	    
213: 	    if( ct_sum_sov > ct_tot ){
214: 	      fct = ct_tot / ( ct_sum_sov - ct_tot );
215: 	    }
216: 	  }
217: 	}
218: 	  	
219: 	double F_ = (double) 0;
220: 	if( considerColorAtoms ){
221: 	  F_ = opt_param*(fst-fct) + fct;
222: 	}else{
223: 	  F_ = fst;
224: 	}
225: 
226: 	if( debug_print1 ) std:: cerr << "\t\tibest_pose: " << ibest_pose << "\tm_loc_: " << m_loc_ << "\tst_tot: " << st_tot << "\tst_sum_sov: " << st_sum_sov << "\tct_tot: " << ct_tot << "\tct_sum_sov: " << ct_sum_sov << "\tfst: " << fst << "\t fct: " << fct << "\t F_: " << F_ << std::endl;
227: 	
228: 	// Find best m_loc
229: 	if( F_ > F ){
230: 	  m_loc = m_loc_;
231: 	  F = F_;
232: 	}
233:       }
234: 
235:       if( debug_print1 ) std:: cerr << "ibest_pose: " << ibest_pose << " FOUND m_loc: " << m_loc << "\tF: " <<  F << "\n";
236: 
237: 	
238:       // Setting "best" m_loc for the current best_pose ibest_pose
239:       memcpy( best_qom_pose[ ibest_pose ], pqmatrix_typed[ ibest_pose ][ m_loc ], 7 * sizeof( double ) );
240:       memcpy( best_mom_pose[ ibest_pose ], pmatrix_typed[ ibest_pose ][ m_loc ], 12 * sizeof( double ) );
241:     }  // end if "qrat"
242:   } // end loop ibest_pose
243: 
244: 
245:   const double  max_quaternion_step  = 0.075;   // Maximum step size for quaternion
246:   const double  max_translation_step = 0.500;   // Maximum step size for translation
247:   const double  min_quaternion_step  = 0.0002;  // Convergence criteria for quaternion
248:   const double  min_translation_step = 0.0020;  // Convergence criteria for translation
249:   const double  min_volume_overlap   = 0.0020;  // Convergence criteria for ST AB volume overlap
250: 	
251:   
252:   // Previous step quaternion/translation and respective 1st derivative gradient
253:   double  old_quattrans_pose[ 16 ][ 7 ];
254:   double old_gradient_pose[ 16 ][ 7 ];
255:   double qstep_size_pose[16];
256:   double tstep_size_pose[ 16 ];
257:   bool allowed_pose[16];
258:   double st_tot_pose[ 16 ];
259:   double fcomb_best_pose[ 16 ];
260:   
261:   for ( unsigned  ibest_pose = 0;  ibest_pose < npose;  ibest_pose++ ) {
262:     allowed_pose[ ibest_pose ] = true;
263:     fcomb_best_pose[ ibest_pose ] = static_cast<double>( 0 );
264:     qstep_size_pose[ ibest_pose ]  = -0.0010;  // Quaternion step size using gradient for direction
265:     tstep_size_pose[ ibest_pose ]  = -0.0100;  // Translation step size using gradient for direction
266:     
267:     // Evaluate the gradient at the starting point
268: 
269:     ComputeOverlapAndAnalyticGradient(
270: 				      st_tot_pose[ ibest_pose ],
271: 				      old_gradient_pose[ ibest_pose ],
272: 				      best_mom_pose[ ibest_pose ],
273: 				      ref_coord,
274: 				      alpha_ref_vector,
275: 				      ref_volumeAtomIndexVector,
276: 				      fit_coord,
277: 				      alpha_fit_vector,
278: 				      fit_volumeAtomIndexVector
279: 				      );
280:    
281:     if( debug_print1 ){
282:       float fst = st_tot_pose[ ibest_pose ] / ( st_sum_sov - st_tot_pose[ ibest_pose ]  );
283:       std::cerr << "\tibest_pose: " << ibest_pose << " Beginning: st_tot: " << st_tot_pose[ ibest_pose ] << "; fst: " << fst << std::endl;
284:     }
285:     
286:   }
287:   
288:   // Loops over cycles, allowed poses and iterations
289:   for( unsigned int icycle=0; icycle < 2; ++icycle ){
290:     for ( unsigned  ibest_pose = 0;  ibest_pose < npose;  ibest_pose++ ) {
291:       
292:       // Beginning of the cycle -- start with old gradient
293:       double  g[ 7 ];
294:       memcpy( g, old_gradient_pose[ ibest_pose ], 7 * sizeof( double ) );
295:       double& qstep_size = qstep_size_pose[ ibest_pose ];
296:       double& tstep_size = tstep_size_pose[ ibest_pose ];
297:       double *old_gradient = old_gradient_pose[ ibest_pose ];
298:       double* old_quattrans = old_quattrans_pose[ ibest_pose ];
299:       double& st_tot = st_tot_pose[ ibest_pose ];
300:       double  *qom = best_qom_pose[ ibest_pose ];
301:       //	double  *mom = best_mom_pose[ ibest_pose ];
302: 
303: 	  
304:       if( icycle == 1 ){ // Beginning of the cycle with icycle=0
305: 
306: 	
307: 	if( debug_print1 ) std::cerr << "*** icycle: " << icycle
308: 				    << " ibest_pose: " << ibest_pose
309: 				    << " nbr_comb_prelim: " << nbr_comb_prelim
310: 				    << " fcomb_best_pose[ ibest_pose ]: " << fcomb_best_pose[ ibest_pose ]
311: 				    << " fcomb_best_pose[ ibest_pose ]/nbr_comb_prelim: " << fcomb_best_pose[ ibest_pose ]/nbr_comb_prelim
312: 				    << std::endl;
313: 	
314: 	if( fcomb_best_pose[ ibest_pose ] <= 0.7 * nbr_comb_prelim ){
315: 	  allowed_pose[ ibest_pose ] = false;
316: 	}
317: 
318: 	if( debug_print1 ){
319: 	  if( allowed_pose[ ibest_pose ] ){
320: 	    std::cerr << "*** pose: " << ibest_pose << " allowed" << std::endl;
321: 	  }else{
322: 	    std::cerr << "*** pose: " << ibest_pose << " not allowed" << std::endl;
323: 	  }
324: 	}
325:       }
326: 
327:       if( allowed_pose[ ibest_pose ] ){
328: 	if( debug_print1 ) std::cerr << "\tibest_pose: " << ibest_pose << " Compute (non-grid-based) shape volume overlap for the current pose ibest_pose " << ibest_pose << " and its \"best\" starting qom" << std::endl;
329:  
330: 
331: 	
332: 	// Iterations
333: 	unsigned start_iter = 0;
334: 	unsigned end_iter = 0;
335: 	if( icycle == 0 ){
336: 	  end_iter = max_preiters;
337: 	}else{
338: 	  start_iter = max_preiters;
339: 	    end_iter = max_preiters + max_postiters;
340: 	}
341: 	
342: 	for ( unsigned iter = start_iter;  iter < end_iter;  iter++ ) {
343: 	  // Determine the step to take
344: 	  double  quat_squared;  // Scratch for deriving fourth quaternion value [0] from other three [1-3]
345: 	  double  step[ 7 ];  // Actual step taken
346: 	  //                    unsigned  ustep[ 6 ];  // Standard step size
347: 
348: 	  // If not first iteration and if we bracketed the maximum, use old step
349: 	  bool  converged = false;
350: 	  if ( 0 == iter ) {
351: 	    // 1st iteration through, use the default step size
352: 	    //                        double  
353: 	    step[ 1 ] = qstep_size * g[ 1 ];
354: 	    step[ 2 ] = qstep_size * g[ 2 ];
355: 	    step[ 3 ] = qstep_size * g[ 3 ];
356: 	    step[ 4 ] = tstep_size * g[ 4 ];
357: 	    step[ 5 ] = tstep_size * g[ 5 ];
358: 	    step[ 6 ] = tstep_size * g[ 6 ];
359: 	  } else {
360: 	    if ( std::signbit( g[ 1 ] ) != std::signbit( old_gradient[ 1 ] ) ) {
361: 	      step[ 1 ] = ( ( ( qom[ 1 ] * fabs( old_gradient[ 1 ] ) ) + ( old_quattrans[ 1 ] * fabs( g[ 1 ] ) ) )
362: 			    / ( fabs( old_gradient[ 1 ] ) + fabs( g[ 1 ] ) ) ) - qom[ 1 ];
363: 	      double  new_step = qstep_size * g[ 1 ];
364: 	      if ( fabs( step[ 1 ] ) > fabs( new_step ) ) {
365: 		step[ 1 ] *= fabs( new_step / step[ 1 ] );
366: 	      }
367: 	    } else {
368: 	      step[ 1 ] = qstep_size * g[ 1 ];
369: 	    }
370: 
371: 	    if ( std::signbit( g[ 2 ] ) != std::signbit( old_gradient[ 2 ] ) ) {
372: 	      step[ 2 ] = ( ( ( qom[ 2 ] * fabs( old_gradient[ 2 ] ) ) + ( old_quattrans[ 2 ] * fabs( g[ 2 ] ) ) )
373: 			    / ( fabs( old_gradient[ 2 ] ) + fabs( g[ 2 ] ) ) ) - qom[ 2 ];
374: 	      double  new_step = qstep_size * g[ 2 ];
375: 	      if ( fabs( step[ 2 ] ) > fabs( new_step ) ) {
376: 		step[ 2 ] *= fabs( new_step / step[ 2 ] );
377: 	      }
378: 	    } else {
379: 	      step[ 2 ] = qstep_size * g[ 2 ];
380: 	    }
381: 
382: 	    if ( std::signbit( g[ 3 ] ) != std::signbit( old_gradient[ 3 ] ) ) {
383: 	      step[ 3 ] = ( ( ( qom[ 3 ] * fabs( old_gradient[ 3 ] ) ) + ( old_quattrans[ 3 ] * fabs( g[ 3 ] ) ) )
384: 			    / ( fabs( old_gradient[ 3 ] ) + fabs( g[ 3 ] ) ) ) - qom[ 3 ];
385: 	      double  new_step = qstep_size * g[ 3 ];
386: 	      if ( fabs( step[ 3 ] ) > fabs( new_step ) ) {
387: 		step[ 3 ] *= fabs( new_step / step[ 3 ] );
388: 	      }
389: 	    } else {
390: 	      step[ 3 ] = qstep_size * g[ 3 ];
391: 	    }
392: 
393: 	    if ( std::signbit( g[ 4 ] ) != std::signbit( old_gradient[ 4 ] ) ) {
394: 	      step[ 4 ] = ( ( ( qom[ 4 ] * fabs( old_gradient[ 4 ] ) ) + ( old_quattrans[ 4 ] * fabs( g[ 4 ] ) ) )
395: 			    / ( fabs( old_gradient[ 4 ] ) + fabs( g[ 4 ] ) ) ) - qom[ 4 ];
396: 	      double  new_step = tstep_size * g[ 4 ];
397: 	      if ( fabs( step[ 4 ] ) > fabs( new_step ) ) {
398: 		step[ 4 ] *= fabs( new_step / step[ 4 ] );
399: 	      }
400: 	    } else {
401: 	      step[ 4 ] = tstep_size * g[ 4 ];
402: 	    }
403: 
404: 	    if ( std::signbit( g[ 5 ] ) != std::signbit( old_gradient[ 5 ] ) ) {
405: 	      step[ 5 ] = ( ( ( qom[ 5 ] * fabs( old_gradient[ 5 ] ) ) + ( old_quattrans[ 5 ] * fabs( g[ 5 ] ) ) )
406: 			    / ( fabs( old_gradient[ 5 ] ) + fabs( g[ 5 ] ) ) ) - qom[ 5 ];
407: 	      double  new_step = tstep_size * g[ 5 ];
408: 	      if ( fabs( step[ 5 ] ) > fabs( new_step ) ) {
409: 		step[ 5 ] *= fabs( new_step / step[ 5 ] );
410: 	      }
411: 	    } else {
412: 	      step[ 5 ] = tstep_size * g[ 5 ];
413: 	    }
414: 
415: 	    if ( std::signbit( g[ 6 ] ) != std::signbit( old_gradient[ 6 ] ) ) {
416: 	      step[ 6 ] = ( ( ( qom[ 6 ] * fabs( old_gradient[ 6 ] ) ) + ( old_quattrans[ 6 ] * fabs( g[ 6 ] ) ) )
417: 			    / ( fabs( old_gradient[ 6 ] ) + fabs( g[ 6 ] ) ) ) - qom[ 6 ];
418: 	      double  new_step = tstep_size * g[ 6 ];
419: 	      if ( fabs( step[ 6 ] ) > fabs( new_step ) ) {
420: 		step[ 6 ] *= fabs( new_step / step[ 6 ] );
421: 	      }
422: 	    } else {
423: 	      step[ 6 ] = tstep_size * g[ 6 ];
424: 	    }
425: 	  }
426: 
427: 	  // Retain last step information in case we are not happy with "line search"
428: 	  double  old_overlap = st_tot;
429: 	  memcpy( old_quattrans, qom, 7 * sizeof( double ) );
430: 	  memcpy( old_gradient, g, 7 * sizeof( double ) );
431: 
432: 	  if( debug_print1 ) std::cerr << "\t\tibest_pose: " << ibest_pose << " iter: " << iter << "\tOld overlap: " << old_overlap << std::endl;
433: 
434: 	  //
435: 	  // Line search (sort of) loop
436: 	  //
437: 	  for ( unsigned  line_iter = 0;  false == converged;  line_iter++ ) {
