98:             { "acceptor", 1 },
99:             { "anion", 2 },
100:             { "cation", 3 },
101:             { "donor", 4 },
102:             { "hydrophobe", 5 },
103:             { "rings", 6 },
104:         };
105: 
106:         string features;
107:         mol.getProp("PUBCHEM_PHARMACOPHORE_FEATURES", features);
108:         istringstream iss(features);
109:         string line;
110:         unsigned int n = 0;
111:         while (getline(iss, line)) {
112:             
113:             if (n == 0) {
114:                 feature_idx_type.resize(stoul(line));
115:             } 
116:             
117:             else {
118:                 unsigned int f = n - 1;
119:                 if (f >= feature_idx_type.size())
120:                     ERRORTHROW("Too many features");
121:                     
122:                 istringstream iss2(line);
123:                 string token;
124:                 unsigned int t = 0;
125:                 while (getline(iss2, token, ' ')) {
126:                     if (t == 0) {
127:                         feature_idx_type[f].first.resize(stoul(token));
