687	unsigned CalculateQrat( const float* ev_ncbi, const float threshold ){
688	
689	
690	
691	  
692	  float double_ev_oe[3];
693	  double_ev_oe[0] = ev_ncbi[1] + ev_ncbi[2] - ev_ncbi[0];
694	  double_ev_oe[1] = ev_ncbi[0] + ev_ncbi[2] - ev_ncbi[1];
695	  double_ev_oe[2] = ev_ncbi[0] + ev_ncbi[1] - ev_ncbi[2];
696	  
697	  /////  std::cerr << "** 1 ** double_EV_oe: " << double_ev_oe[0] << " " << double_ev_oe[1] << " " << double_ev_oe[2] << std::endl;
698	
699	  std::sort( double_ev_oe, double_ev_oe+3, std::greater<float>());
700	
701	  ////  std::cerr << "** 2 ** double_EV_oe: " << double_ev_oe[0] << " " << double_ev_oe[1] << " " << double_ev_oe[2] << std::endl;
702	
703	
704	  Uint8  u_rqyx, u_rqzy;
705	  unsigned qrat = 1000;
706	  if( double_ev_oe[1] > 0 ){
707	    if ( threshold < ( double_ev_oe[1] / double_ev_oe[0] ) ) {
708	      u_rqyx = 1;
709	    } else {
710	      u_rqyx = 0;
711	    }
712	    if ( threshold < ( double_ev_oe[2] / double_ev_oe[1] ) ) {
713	      u_rqzy = 1;
714	    } else {
715	      u_rqzy = 0;
716	    }
717	    
718	    qrat = u_rqyx + u_rqzy;
719	  }
720	      
721	  return qrat;
722	}
